import { useId, type FormEvent, type KeyboardEvent } from "react";
import "./CommandBox.css";

export interface CommandReply {
  text: string;
  isError?: boolean;
}

export interface CommandBoxProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (value: string) => void;
  reply?: CommandReply;
  placeholder?: string;
}

export function CommandBox({
  value,
  onChange,
  onSubmit,
  reply,
  placeholder = "Type a command",
}: CommandBoxProps) {
  const inputId = useId();
  const replyId = useId();

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const command = value.trim();
    if (command === "") {
      return;
    }
    onSubmit(command);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Escape" && value !== "") {
      event.preventDefault();
      onChange("");
    }
  };

  const replyClass = reply?.isError ? "command-reply is-error" : "command-reply";

  return (
    <div className="command-box">
      <form className="command-row" onSubmit={handleSubmit}>
        <label className="sr-only" htmlFor={inputId}>
          Command
        </label>
        <input
          id={inputId}
          className="command-input"
          type="text"
          autoComplete="off"
          spellCheck={false}
          placeholder={placeholder}
          value={value}
          onChange={(event) => onChange(event.target.value)}
          onKeyDown={handleKeyDown}
          aria-describedby={reply ? replyId : undefined}
          aria-invalid={reply?.isError ? true : undefined}
        />
        <button type="submit" className="command-submit">
          Run
        </button>
      </form>
      {reply ? (
        <p
          id={replyId}
          className={replyClass}
          role={reply.isError ? "alert" : "status"}
        >
          {reply.text}
        </p>
      ) : null}
    </div>
  );
}
